pub const fn aatrox_p(ctx: &Ctx) -> f32 {
    4.04 + 0.0035 * (-1f32 + ctx.level) + 6f32 * (-1f32 + ctx.level) / 17f32
}

pub const fn aatrox_qmin(ctx: &Ctx) -> f32 {
    37.5 + 56.25 * (-1f32 + ctx.q_level)
        + ctx.attack_damage * (0.6 + 0.075 * (-1f32 + ctx.q_level))
        + ctx.attack_damage * (0.75 + 0.09375 * (-1f32 + ctx.q_level))
        + ctx.attack_damage * (0.9 + 0.1125 * (-1f32 + ctx.q_level))
}

pub const fn aatrox_q1min(ctx: &Ctx) -> f32 {
    10f32
        + 15f32 * (-1f32 + ctx.q_level)
        + ctx.attack_damage * (0.6 + 0.075 * (-1f32 + ctx.q_level))
}

pub const fn aatrox_q2min(ctx: &Ctx) -> f32 {
    12.5 + 18.75 * (-1f32 + ctx.q_level)
        + ctx.attack_damage * (0.75 + 0.09375 * (-1f32 + ctx.q_level))
}

pub const fn aatrox_q3min(ctx: &Ctx) -> f32 {
    15f32
        + 22.5 * (-1f32 + ctx.q_level)
        + ctx.attack_damage * (0.9 + 0.1125 * (-1f32 + ctx.q_level))
}

pub const fn aatrox_qmax(ctx: &Ctx) -> f32 {
    63.75
        + 95.625 * (-1f32 + ctx.q_level)
        + ctx.attack_damage * (1.02 + 0.1275 * (-1f32 + ctx.q_level))
        + ctx.attack_damage * (1.275 + 0.159375 * (-1f32 + ctx.q_level))
        + ctx.attack_damage * (1.53 + 0.19125 * (-1f32 + ctx.q_level))
}

pub const fn aatrox_q1max(ctx: &Ctx) -> f32 {
    17f32
        + 25.5 * (-1f32 + ctx.q_level)
        + ctx.attack_damage * (1.02 + 0.1275 * (-1f32 + ctx.q_level))
}

pub const fn aatrox_q2max(ctx: &Ctx) -> f32 {
    21.25
        + 31.875 * (-1f32 + ctx.q_level)
        + ctx.attack_damage * (1.275 + 0.159375 * (-1f32 + ctx.q_level))
}

pub const fn aatrox_q3max(ctx: &Ctx) -> f32 {
    25.5 + 38.25 * (-1f32 + ctx.q_level)
        + ctx.attack_damage * (1.53 + 0.19125 * (-1f32 + ctx.q_level))
}

pub const fn aatrox_wmin(ctx: &Ctx) -> f32 {
    10f32 * (2f32 + 0.04 * ctx.attack_damage + ctx.w_level)
}

pub const fn aatrox_wmax(ctx: &Ctx) -> f32 {
    20f32 * (2f32 + 0.04 * ctx.attack_damage + ctx.w_level)
}

