pub const fn ambessa_p1(ctx: &Ctx) -> f32 {
    5f32 + 0.25 * ctx.bonus_ad + 25f32 * (-1f32 + ctx.level) / 17f32
}

pub const fn ambessa_p2(ctx: &Ctx) -> f32 {
    5f32 + 1.47 * (-1f32 + ctx.level)
}

pub const fn ambessa_p3(ctx: &Ctx) -> f32 {
    ctx.attack_speed / 2f32
}

pub const fn ambessa_p4(ctx: &Ctx) -> f32 {
    5f32 + 1.47 * (-1f32 + ctx.level)
}

pub const fn ambessa_p5(ctx: &Ctx) -> f32 {
    match ctx.level as u8 {
        ..7 => 40f32,
        7..13 => 55f32,
        13.. => 70f32,
    }
}

pub const fn ambessa_q1(ctx: &Ctx) -> f32 {
    40f32
        + 0.6 * ctx.bonus_ad
        + 20f32 * (-1f32 + ctx.q_level)
        + ctx.enemy_max_health
            * (0.04 + 0.0003 * ctx.bonus_ad + 0.005 * (-1f32 + ctx.q_level))
}

