pub const fn briar_p1(ctx: &Ctx) -> f32 {
    10f32 + 0.125 * ctx.bonus_ad + 40f32 * (-1f32 + ctx.level) / 17f32
}

pub const fn briar_p2(ctx: &Ctx) -> f32 {
    2.5 + 0.59 * (-1f32 + ctx.level)
}

pub const fn briar_p3(ctx: &Ctx) -> f32 {
    0.63 + 0.14 * (-1f32 + ctx.level)
}

pub const fn briar_p4(ctx: &Ctx) -> f32 {
    4f32 * (5f32 + 1.1775 * (-1f32 + ctx.level))
}

pub const fn briar_p5(ctx: &Ctx) -> f32 {
    5f32 + 1.18 * (-1f32 + ctx.level)
}

pub const fn briar_p6(ctx: &Ctx) -> f32 {
    1f32 + 0.24 * (-1f32 + ctx.level)
}

pub const fn briar_p7(ctx: &Ctx) -> f32 {
    ctx.bonus_ad * (0.25 + 0.06 * (-1f32 + ctx.level))
}

pub const fn briar_p8(ctx: &Ctx) -> f32 {
    ctx.bonus_ad * (0.06 + 0.02 * (-1f32 + ctx.level))
}

pub const fn briar_p1min(ctx: &Ctx) -> f32 {
    2f32 + 0.47 * (-1f32 + ctx.level)
}

pub const fn briar_p2min(ctx: &Ctx) -> f32 {
    0.5 + 0.12 * (-1f32 + ctx.level)
}

pub const fn briar_p3min(ctx: &Ctx) -> f32 {
    0.03125 * ctx.bonus_ad
}

pub const fn briar_p4min(ctx: &Ctx) -> f32 {
    0.05 * ctx.bonus_ad
}

pub const fn briar_p5min(ctx: &Ctx) -> f32 {
    0.0125 * ctx.bonus_ad
}

pub const fn briar_p6min(ctx: &Ctx) -> f32 {
    0.003125 * ctx.bonus_ad
}

pub const fn briar_p7min(ctx: &Ctx) -> f32 {
    0.1 * ctx.bonus_ad
}

pub const fn briar_p8min(ctx: &Ctx) -> f32 {
    0.025 * ctx.bonus_ad
}

pub const fn briar_p1max(ctx: &Ctx) -> f32 {
    0.25 * ctx.stacks
}

pub const fn briar_p2max(ctx: &Ctx) -> f32 {
    1.25 * ctx.steelcaps_effect
}

pub const fn briar_p3max(ctx: &Ctx) -> f32 {
    2f32 * (5f32 + 1.175 * (-1f32 + ctx.level))
}

pub const fn briar_q(ctx: &Ctx) -> f32 {
    5f32 * (12f32
        + 0.12 * ctx.ability_power
        + 0.16 * ctx.bonus_ad
        + 5f32 * (-1f32 + ctx.q_level))
}

pub const fn briar_w(ctx: &Ctx) -> f32 {
    5f32 + 0.05 * ctx.attack_damage
        + 15f32 * (-1f32 + ctx.w_level)
        + ctx.enemy_missing_health * (0.09 + 0.00025 * ctx.bonus_ad)
}

pub const fn briar_e2(ctx: &Ctx) -> f32 {
    140f32
        + 2.4 * ctx.ability_power
        + 2.4 * ctx.bonus_ad
        + 75f32 * (-1f32 + ctx.e_level)
}

pub const fn briar_emin(ctx: &Ctx) -> f32 {
    2f32 + 0.025 * ctx.ability_power
        + 0.025 * ctx.bonus_ad
        + 0.875 * (-1f32 + ctx.e_level)
}

pub const fn briar_emax(ctx: &Ctx) -> f32 {
    80f32 + ctx.ability_power + ctx.bonus_ad + 35f32 * (-1f32 + ctx.e_level)
}

pub const fn briar_e1max(ctx: &Ctx) -> f32 {
    220f32
        + 3.4 * ctx.ability_power
        + 3.4 * ctx.bonus_ad
        + 110f32 * (-1f32 + ctx.e_level)
}

pub const fn briar_r(ctx: &Ctx) -> f32 {
    150f32 + 1.3 * ctx.ability_power + 100f32 * (-1f32 + ctx.r_level)
}

