pub const fn draven_q(ctx: &Ctx) -> f32 {
    40f32
        + 5f32 * (-1f32 + ctx.q_level)
        + ctx.bonus_ad * (0.75 + 0.1 * (-1f32 + ctx.q_level))
}

pub const fn draven_e(ctx: &Ctx) -> f32 {
    75f32 + 35f32 * (-1f32 + ctx.e_level) + ctx.bonus_ad / 2f32
}

pub const fn draven_rmin(ctx: &Ctx) -> f32 {
    160f32
        + 80f32 * (-1f32 + ctx.r_level)
        + ctx.bonus_ad * (0.88 + 0.08 * (-1f32 + ctx.r_level))
}

pub const fn draven_r1min(ctx: &Ctx) -> f32 {
    80f32
        + 40f32 * (-1f32 + ctx.r_level)
        + ctx.bonus_ad * (0.44 + 0.04 * (-1f32 + ctx.r_level))
}

pub const fn draven_rmax(ctx: &Ctx) -> f32 {
    400f32
        + 200f32 * (-1f32 + ctx.r_level)
        + ctx.bonus_ad * (2.2 + 0.2 * (-1f32 + ctx.r_level))
}

pub const fn draven_r1max(ctx: &Ctx) -> f32 {
    200f32
        + 100f32 * (-1f32 + ctx.r_level)
        + ctx.bonus_ad * (1.1 + 0.1 * (-1f32 + ctx.r_level))
}

